import java.util.*;

public class Solution {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (!sc.hasNextInt()) return;
        int n = sc.nextInt();
        if (n <= 0) return;
        int[] vals = new int[n];
        for (int i = 0; i < n; i++) vals[i] = sc.nextInt();
        if (vals[0] == -1) return;

        Queue<Integer> q = new LinkedList<>();
        q.add(0);
        while (!q.isEmpty()) {
            int sz = q.size();
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < sz; i++) {
                int curr = q.poll();
                sb.append(vals[curr]).append(i == sz - 1 ? "" : " ");
                int left = 2 * curr + 1;
                int right = 2 * curr + 2;
                if (left < n && vals[left] != -1) q.add(left);
                if (right < n && vals[right] != -1) q.add(right);
            }
            System.out.println(sb.toString());
        }
    }
}

