#include <stdio.h>
#include <stdlib.h>

int main() {
    int n;
    if (scanf("%d", &n) != 1 || n <= 0) return 0;
    int *vals = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) scanf("%d", &vals[i]);
    if (vals[0] == -1) { free(vals); return 0; }

    int *queue = malloc(n * sizeof(int));
    int head = 0, tail = 0;
    queue[tail++] = 0;

    while (head < tail) {
        int sz = tail - head;
        for (int i = 0; i < sz; i++) {
            int curr = queue[head++];
            printf("%d%s", vals[curr], i == sz - 1 ? "\n" : " ");
            int left = 2 * curr + 1;
            int right = 2 * curr + 2;
            if (left < n && vals[left] != -1) queue[tail++] = left;
            if (right < n && vals[right] != -1) queue[tail++] = right;
        }
    }
    free(vals);
    free(queue);
    return 0;
}
